// Original — Frictionborn Motion
"use client";

import React, { useEffect, useRef } from "react";
import { createSurface, type Surface } from "@frictionborn/runtime/gl";
import { useFrame, useFrameGuard } from "@frictionborn/runtime";
import { vertexShaderSource, fragmentShaderSource } from "./shaders/noise.glsl";

export interface NoiseFieldGLProps {
  colors: [string, string, string];
  speed?: number;
  scale?: number;
  intensity?: number;
  paused?: boolean;
  time?: number;
  tier?: number;
  reducedMotion?: boolean;
  onContextLost?: () => void;
  onContextRestored?: () => void;
  onDowngrade?: () => void;
}

function parseColor(hexOrCss: string): [number, number, number] {
  if (hexOrCss.startsWith("#")) {
    let hex = hexOrCss.slice(1);
    if (hex.length === 3) {
      hex = hex.split("").map((c) => c + c).join("");
    }
    const num = parseInt(hex, 16);
    return [
      ((num >> 16) & 255) / 255,
      ((num >> 8) & 255) / 255,
      (num & 255) / 255,
    ];
  }
  // Fallback dark ember palette
  return [0.05, 0.06, 0.08];
}

export default function NoiseFieldGL({
  colors,
  speed = 1.0,
  scale = 1.8,
  intensity = 1.0,
  paused = false,
  time,
  tier = 3,
  reducedMotion = false,
  onContextLost,
  onContextRestored,
  onDowngrade,
}: NoiseFieldGLProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const surfaceRef = useRef<Surface | null>(null);
  const programRef = useRef<WebGLProgram | null>(null);
  const uniformsRef = useRef<{
    resolution?: WebGLUniformLocation;
    time?: WebGLUniformLocation;
    speed?: WebGLUniformLocation;
    scale?: WebGLUniformLocation;
    intensity?: WebGLUniformLocation;
    color1?: WebGLUniformLocation;
    color2?: WebGLUniformLocation;
    color3?: WebGLUniformLocation;
  }>({});
  const timeRef = useRef<number>(time ?? 0);

  // Monitor frame timings and trigger downgrade if performance degrades
  useFrameGuard({ onDowngrade: () => onDowngrade?.(), active: !paused && !reducedMotion }); // @frictionborn-guard

  const maxDpr = tier >= 3 ? 2.0 : 1.5;
  const renderScale = tier >= 3 ? 1.0 : 0.75;

  const onContextLostRef = useRef(onContextLost);
  onContextLostRef.current = onContextLost;
  const onContextRestoredRef = useRef(onContextRestored);
  onContextRestoredRef.current = onContextRestored;

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const canvas = document.createElement("canvas");
    canvas.setAttribute("aria-hidden", "true");
    canvas.style.position = "absolute";
    canvas.style.inset = "0";
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    canvas.style.display = "block";
    canvas.style.pointerEvents = "none";
    container.appendChild(canvas);

    try {
      const surface = createSurface(canvas, {
        maxDpr,
        scale: renderScale,
        onContextLost: () => {
          onContextLostRef.current?.();
        },
        onContextRestored: () => {
          onContextRestoredRef.current?.();
        },
      }); // @frictionborn-guard

      surfaceRef.current = surface;
      const gl = surface.gl;

      const program = surface.createProgram(vertexShaderSource, fragmentShaderSource);
      programRef.current = program;

      uniformsRef.current = {
        resolution: gl.getUniformLocation(program, "u_resolution") || undefined,
        time: gl.getUniformLocation(program, "u_time") || undefined,
        speed: gl.getUniformLocation(program, "u_speed") || undefined,
        scale: gl.getUniformLocation(program, "u_scale") || undefined,
        intensity: gl.getUniformLocation(program, "u_intensity") || undefined,
        color1: gl.getUniformLocation(program, "u_color1") || undefined,
        color2: gl.getUniformLocation(program, "u_color2") || undefined,
        color3: gl.getUniformLocation(program, "u_color3") || undefined,
      };

      // Draw initial frame immediately (required for reduced-motion still frame)
      renderFrame(timeRef.current);
    } catch (err) {
      console.warn("NoiseField WebGL2 initialization failed; falling back to poster", err);
      if (surfaceRef.current) {
        surfaceRef.current.dispose(); // @frictionborn-guard
        surfaceRef.current = null;
      }
      onContextLostRef.current?.();
    }

    return () => {
      if (surfaceRef.current) {
        surfaceRef.current.dispose(); // @frictionborn-guard
        surfaceRef.current = null;
      }
      canvas.remove();
    };
  }, [maxDpr, renderScale]);

  function renderFrame(currentTime: number) {
    const surface = surfaceRef.current;
    const program = programRef.current;
    if (!surface || !program) return;

    const gl = surface.gl;
    const u = uniformsRef.current;

    gl.useProgram(program);

    if (u.resolution) {
      gl.uniform2f(u.resolution, gl.drawingBufferWidth, gl.drawingBufferHeight);
    }
    if (u.time) {
      gl.uniform1f(u.time, currentTime);
    }
    if (u.speed) {
      gl.uniform1f(u.speed, speed);
    }
    if (u.scale) {
      gl.uniform1f(u.scale, scale);
    }
    if (u.intensity) {
      gl.uniform1f(u.intensity, intensity);
    }

    const c1 = parseColor(colors[0]);
    const c2 = parseColor(colors[1]);
    const c3 = parseColor(colors[2]);

    if (u.color1) gl.uniform3f(u.color1, c1[0], c1[1], c1[2]);
    if (u.color2) gl.uniform3f(u.color2, c2[0], c2[1], c2[2]);
    if (u.color3) gl.uniform3f(u.color3, c3[0], c3[1], c3[2]);

    surface.draw();
  }

  // Animation loop subscribed via shared runtime useFrame (never raw rAF)
  useFrame(
    ({ dt }) => {
      if (time !== undefined) {
        timeRef.current = time;
      } else {
        timeRef.current += (dt * 0.001) * speed;
      }
      renderFrame(timeRef.current);
    },
    { active: !paused && !reducedMotion } // @frictionborn-guard
  );

  return (
    <div
      ref={containerRef}
      aria-hidden="true"
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        overflow: "hidden",
        pointerEvents: "none",
      }}
    />
  );
}

/* Original — Frictionborn Motion */
.container {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--fb-bg, #0D0F12);
}

.poster {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  z-index: 1;
}

.canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 2;
  opacity: 1;
  pointer-events: none;
}

/* Subtle crossfade only after motion is confirmed ready */
[data-motion="ok"] .canvas {
  transition: opacity var(--fb-duration-base, 400ms) var(--fb-ease-out, cubic-bezier(0.22, 1, 0.36, 1));
}

.scrim {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background: radial-gradient(
    circle at center,
    rgba(13, 15, 18, 0.25) 0%,
    rgba(13, 15, 18, 0.75) 100%
  );
}

.content {
  position: relative;
  z-index: 4;
  width: 100%;
  height: 100%;
}

// Original — Frictionborn Motion
"use client";

import React, { useState, useEffect, useRef, useCallback, Suspense, lazy } from "react";
import {
  useCapability,
  useHydrated,
  useReducedMotion,
  useInView,
  glBudget,
  type Lease,
} from "@frictionborn/runtime";

const NoiseFieldGL = lazy(() => import("./noise-field.gl"));

export interface NoiseFieldProps extends React.HTMLAttributes<HTMLDivElement> {
  colors?: [string, string, string];
  speed?: number;
  scale?: number;
  intensity?: number;
  scrim?: boolean;
  paused?: boolean;
  time?: number;
  maxTier?: number;
  children?: React.ReactNode;
}

export function NoiseField({
  colors = ["#0D0F12", "#FB923C", "#3B82F6"],
  speed = 1.0,
  scale = 1.8,
  intensity = 1.0,
  scrim = true,
  paused = false,
  time,
  maxTier = 3,
  className = "",
  style,
  children,
  ...props
}: NoiseFieldProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const hydrated = useHydrated(); // @frictionborn-guard
  const cap = useCapability(); // @frictionborn-guard
  const reduced = useReducedMotion(); // @frictionborn-guard
  const inView = useInView(containerRef); // @frictionborn-guard

  const [hasLease, setHasLease] = useState(false);
  const leaseRef = useRef<Lease | null>(null);
  const [contextLost, setContextLost] = useState(false);
  const [effectiveTier, setEffectiveTier] = useState<number>(3);

  // Determine active tier considering cap, maxTier and context state
  const computedTier = Math.min(cap.tier, maxTier);

  useEffect(() => {
    setEffectiveTier(computedTier);
  }, [computedTier]);

  // Context lease acquisition (PRD 6.0 + 6.1)
  useEffect(() => {
    // Only acquire WebGL context if hydrated, visible, tier >= 2, and context is healthy
    const shouldAcquire = hydrated && inView && effectiveTier >= 2 && !contextLost;

    if (shouldAcquire && !leaseRef.current) {
      const newLease = glBudget.acquire({ id: "noise-field", priority: 1 }); // @frictionborn-guard
      if (newLease) {
        leaseRef.current = newLease;
        setHasLease(true);
      }
    } else if (!shouldAcquire && leaseRef.current) {
      leaseRef.current.release(); // @frictionborn-guard
      leaseRef.current = null;
      setHasLease(false);
    }
  }, [hydrated, inView, effectiveTier, contextLost]);

  useEffect(() => {
    return () => {
      if (leaseRef.current) {
        leaseRef.current.release(); // @frictionborn-guard
        leaseRef.current = null;
      }
    };
  }, []);

  // CSS poster generated from the identical 3-color palette (CLS 0)
  const posterStyle: React.CSSProperties = {
    position: "absolute",
    inset: 0,
    width: "100%",
    height: "100%",
    background: `radial-gradient(circle at 35% 25%, ${colors[1]}33 0%, transparent 65%), radial-gradient(circle at 75% 75%, ${colors[2]}33 0%, transparent 55%), ${colors[0]}`,
    zIndex: 1,
  };

  const handleDowngrade = useCallback(() => {
    setEffectiveTier((prev) => Math.max(0, prev - 1)); // @frictionborn-guard
  }, []);

  const handleContextLost = useCallback(() => {
    setContextLost(true); // @frictionborn-guard
    if (leaseRef.current) {
      leaseRef.current.release();
      leaseRef.current = null;
      setHasLease(false);
    }
  }, []);

  const handleContextRestored = useCallback(() => {
    setContextLost(false); // @frictionborn-guard
  }, []);

  const canRenderWebGL = hydrated && inView && effectiveTier >= 2 && hasLease && !contextLost;

  return (
    <div
      ref={containerRef}
      data-frictionborn-item="noise-field"
      data-tier={effectiveTier}
      data-in-view={inView}
      data-reduced-motion={reduced}
      className={`relative w-full h-full min-h-[300px] overflow-hidden ${className}`}
      style={{ backgroundColor: colors[0], ...style }}
      {...props}
    >
      {/* 1. Server-rendered CSS gradient poster always present as fallback (CLS 0) */}
      <div style={posterStyle} aria-hidden="true" />

      {/* 2. WebGL canvas rendered client-side only when lease granted */}
      {canRenderWebGL && (
        <Suspense fallback={null}>
          <NoiseFieldGL
            colors={colors}
            speed={speed}
            scale={scale}
            intensity={intensity}
            paused={paused}
            time={time}
            tier={effectiveTier}
            reducedMotion={reduced}
            onContextLost={handleContextLost}
            onContextRestored={handleContextRestored}
            onDowngrade={handleDowngrade}
          />
        </Suspense>
      )}

      {/* 3. Scrim layer preserving WCAG contrast >= 4.5:1 for overlaid text */}
      {scrim && (
        <div
          aria-hidden="true"
          style={{
            position: "absolute",
            inset: 0,
            zIndex: 3,
            pointerEvents: "none",
            background:
              "radial-gradient(circle at center, rgba(13, 15, 18, 0.25) 0%, rgba(13, 15, 18, 0.75) 100%)",
          }}
        />
      )}

      {/* 4. Children slot */}
      {children && (
        <div style={{ position: "relative", zIndex: 4, width: "100%", height: "100%" }}>
          {children}
        </div>
      )}
    </div>
  );
}

// Original — Frictionborn Motion
export const vertexShaderSource = `#version 300 es
in vec2 position;
out vec2 v_uv;

void main() {
  v_uv = (position + 1.0) * 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

export const fragmentShaderSource = `#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform vec2 u_resolution;
uniform float u_time;
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform vec3 u_color1;
uniform vec3 u_color2;
uniform vec3 u_color3;

// Original hash function
vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}

// 2D Value-Gradient noise
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);

  return mix(
    mix(dot(hash2(i + vec2(0.0, 0.0)), f - vec2(0.0, 0.0)),
        dot(hash2(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0)), u.x),
    mix(dot(hash2(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0)),
        dot(hash2(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0)), u.x),
    u.y
  );
}

// 4-octave Fractional Brownian Motion
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  vec2 shift = vec2(100.0);
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < 4; ++i) {
    v += a * noise(p);
    p = rot * p * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
  vec2 p = (gl_FragCoord.xy * 2.0 - u_resolution.xy) / min(u_resolution.x, u_resolution.y);
  p *= (u_scale > 0.0 ? u_scale : 1.8);

  float t = u_time * (u_speed > 0.0 ? u_speed : 0.08);

  // Domain warping: warps coordinates through nested fbm stages
  vec2 q = vec2(fbm(p + vec2(0.0, t * 0.4)), fbm(p + vec2(5.2, 1.3 - t * 0.3)));
  vec2 r = vec2(fbm(p + 3.0 * q + vec2(1.7 - t * 0.2, 9.2)), fbm(p + 3.0 * q + vec2(8.3, 2.8 + t * 0.15)));
  float f = fbm(p + 3.5 * r);

  float normF = clamp(f * 0.5 + 0.5, 0.0, 1.0);
  float normQ = clamp(length(q) * 0.8, 0.0, 1.0);

  // Palette interpolation between 3 theme colors
  vec3 col = mix(u_color1, u_color2, normF);
  col = mix(col, u_color3, normQ * normF);

  // Edge vignette for soft contrast
  float vig = 1.0 - smoothstep(0.4, 1.4, length(uv - 0.5) * 1.5);
  col *= mix(0.75, 1.0, vig);

  fragColor = vec4(col, 1.0);
}
`;
